-- CPU-P01 current release binding from its Ent schema and schema exporter.
-- Limited to the new tenant/preset pointer and its indexes. Historical schema
-- drift for sys_users.avatar, files and the GPU result check is not applied.
CREATE TABLE "public"."sys_modeldev_release_bindings" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL,
  "resource_tenant_id" character varying NOT NULL,
  "preset_id" character varying NOT NULL,
  "release_id" character varying NOT NULL,
  "release_digest" character varying NOT NULL,
  "generation" bigint NOT NULL,
  "new_submissions_enabled" boolean NOT NULL DEFAULT false,
  "updated_by" character varying NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "reason" character varying NOT NULL,
  "evidence_reference" character varying NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "sys_modeldev_release_bindings_tenant_resource_mapping_fkey"
    FOREIGN KEY ("tenant_id", "resource_tenant_id")
    REFERENCES "public"."sys_tenants" ("id", "resource_tenant_id")
    ON UPDATE NO ACTION ON DELETE RESTRICT,
  CONSTRAINT "sys_modeldev_release_bindings_generation_positive_ck"
    CHECK (generation > 0),
  CONSTRAINT "sys_modeldev_release_bindings_tenant_positive_ck"
    CHECK (tenant_id > 0)
);
CREATE UNIQUE INDEX "uix_sys_modeldev_release_bindings_scope"
  ON "public"."sys_modeldev_release_bindings" ("resource_tenant_id", "preset_id");
CREATE UNIQUE INDEX "uix_sys_modeldev_release_bindings_tenant_preset"
  ON "public"."sys_modeldev_release_bindings" ("tenant_id", "preset_id");
